fn round_half_even(x: f64) -> f64 {
    // Implement bankers rounding: ties to even
    let floor = x.floor();
    let ceil = x.ceil();
    let diff_floor = (x - floor).abs();
    let diff_ceil = (ceil - x).abs();
    if (diff_floor - diff_ceil).abs() < 1e-9 {
        // Tie: choose even
        if floor % 2.0 == 0.0 {
            floor
        } else {
            ceil
        }
    } else if diff_floor < diff_ceil {
        floor
    } else {
        ceil
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    // Implement humantime-like parser
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err("value was empty".to_string());
    }
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut i = 0usize;
    let mut total = Duration::new(0,0);
    let mut found = false;
    while i < n {
        // Skip spaces
        while i < n && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= n {
            break;
        }
