        while i < n && (bytes[i].is_ascii_alphabetic()) {
            i += 1;
        }
        if unit_start == i {
            // No unit
            // Error: unknown unit at unit_start-unit_start (if at end) or at unit_start-(i-1)?
            // For "5", unit_start=1, i=1 (end), error at 1-1
            // For "5 " (with trailing space), after number we skipped spaces, unit_start would be at end (n), error at n-n?
            // But original "5" with no unit gives unknown unit at 1-1
            // For case where we have number then invalid character like "1.5s", after parsing number "1", next char is '.', not digit nor space nor alpha, so we go to unit parsing, unit_start =1, bytes[1]=='.', not alpha, so unit_start==i, then we should report invalid character at 1? Actually error for "1.5s" is "invalid character at 1" where position 1 is '.'.
            // So we need to detect invalid character: if current byte is not whitespace, not digit, not alpha, then it's invalid.
            if i < n {
                // Check what char is at i
                let c = bytes[i] as char;
                if c == '.' || c == ',' || c == '-' {
                    return Err(format!("invalid character at {}", i));
                } else {
                    // Unknown unit? But if char is not alpha, it's invalid character?
                    // For "1x" where x is alpha but unknown unit, we return unknown unit, not invalid character.
                    // For "1," invalid character at 1 (comma)
                    // So we need to distinguish: if byte is alpha, it's start of unit, but we already have unit_start==i and no alpha, so next byte is non-alpha non-digit non-space => invalid character.
                    return Err(format!("invalid character at {}", i));
                }
            } else {
                // At end, missing unit
                return Err(format!("unknown unit at {}-{}", unit_start, unit_start));
            }
        }
        let unit_str = &s[unit_start..i];
        // Check if unit_str is valid
        let unit_dur = match unit_str {
            "ns" => Duration::from_nanos(1),
            "nanos" => Duration::from_nanos(1),
            "us" => Duration::from_micros(1),
            "ms" => Duration::from_millis(1),
            "millis" => Duration::from_millis(1),
            "msec" => Duration::from_millis(1),
            "s" => Duration::from_secs(1),
            "sec" => Duration::from_secs(1),
            "secs" => Duration::from_secs(1),
            "second" => Duration::from_secs(1),
            "seconds" => Duration::from_secs(1),
            "m" => Duration::from_secs(60),
            "min" => Duration::from_secs(60),
            "mins" => Duration::from_secs(60),
            "minute" => Duration::from_secs(60),
            "minutes" => Duration::from_secs(60),
            "h" => Duration::from_secs(3600),
            "hour" => Duration::from_secs(3600),
            "hours" => Duration::from_secs(3600),
            "d" => Duration::from_secs(86400),
            "day" => Duration::from_secs(86400),
            "days" => Duration::from_secs(86400),
            "w" => Duration::from_secs(604800),
            "week" => Duration::from_secs(604800),
            "weeks" => Duration::from_secs(604800),
            "y" => Duration::from_secs(31536000), // 365 days
            "year" => Duration::from_secs(31536000),
            "years" => Duration::from_secs(31536000),
            "M" => Duration::from_secs(2592000), // 30 days approx?
            "month" => Duration::from_secs(2592000),
            "months" => Duration::from_secs(2592000),
            _ => {
                // Unknown unit: report range unit_start .. i-1
                return Err(format!("unknown unit at {}-{}", unit_start, i-1));
            }
        };
        // Multiply num * unit_dur, add to total
        // Use checked multiplication
        let add = unit_dur.checked_mul(num as u32).ok_or("duration too large")?;
        total = total.checked_add(add).ok_or("duration too large")?;
        found = true;
        // Loop continue, but need to handle case where after unit there is directly number without space: e.g., "1h2m" => after unit "h" at i, next char is '2' digit, we will loop, skip spaces (none), parse number.
        // Also need to handle invalid characters between: e.g., "1h,2m" => after "h", next char is ',' at i, next iteration will skip spaces? But ',' not space nor digit, so will error as invalid character at position of ','.
    }
    if !found {
        return Err("value was empty".to_string());
    }
    Ok(total)
}

fn parse_until_time(s: &str) -> Result<SystemTime, String> {
    // Try parse "YYYY-MM-DD HH:MM:SS" and "YYYY-MM-DDTHH:MM:SS" in UTC
    // Use chrono
    let fmt1 = "%Y-%m-%d %H:%M:%S";
    let fmt2 = "%Y-%m-%dT%H:%M:%S";
    // Also try with maybe without seconds? But spec shows example with seconds.
    // Use chrono NaiveDateTime parse
    let dt = chrono::NaiveDateTime::parse_from_str(s, fmt1)
        .or_else(|_| chrono::NaiveDateTime::parse_from_str(s, fmt2));
    match dt {
        Ok(naive) => {
            let dt_utc = chrono::DateTime::<chrono::Utc>::from_utc(naive, chrono::Utc);
            Ok(SystemTime::UNIX_EPOCH + Duration::from_secs(dt_utc.timestamp() as u64) + Duration::from_nanos(dt_utc.timestamp_subsec_nanos() as u64))
        },
        Err(_) => Err("timestamp format is invalid".to_string()),
    }
}
RS
